   159	export function computeShovelKinematics(
   160	  timeSec: number,
   161	  phaseOffset: number,
   162	  halted: boolean
   163	): ShovelPose {
   164	  if (halted) {
   165	    return {
   166	      swingAngle: -0.25,
   167	      boomPitch: 0,
   168	      stickExtension: -0.8,
   169	      bucketCurl: -0.35,
   170	    };
   171	  }
